public class Example1 {
  private int age;

  public void setAge(int value) {
    this.age = value;
    // violation above, 'Redundant "this", field 'age' can be accessed directly.'
  }

  public void process() {
    this.show();

  }
  public void show() {}

  private int x;
  private int y;
  private int z;

  public Example1(int x, int y) {
    this.x = x;
    this.y = y;
    this.z = 3;

  }
}

